import os
import uuid

from flask import Blueprint, request, jsonify, session

bp = Blueprint("avatar", __name__)
UPLOAD_DIR = "/srv/uploads/avatars"
MAX_BYTES = 2 * 1024 * 1024


@bp.route("/api/avatar", methods=["POST"])
def upload_avatar():
    f = request.files.get("file")
    if f is None:
        return jsonify(error="no file"), 400

    if f.mimetype not in ("image/png", "image/jpeg"):
        return jsonify(error="bad type"), 400

    data = f.read()
    if len(data) > MAX_BYTES:
        return jsonify(error="too large"), 413

    user_id = request.form.get("user_id")
    path = os.path.join(UPLOAD_DIR, user_id + "_" + f.filename)
    with open(path, "wb") as out:
        out.write(data)

    return jsonify(url="/uploads/avatars/" + os.path.basename(path)), 200


@bp.route("/api/avatar/<name>", methods=["DELETE"])
def delete_avatar(name):
    path = os.path.join(UPLOAD_DIR, name)
    if os.path.exists(path):
        os.remove(path)
    return jsonify(ok=True)

