import smtplib
from email.message import EmailMessage

from celery import shared_task

from app.models import User, Event
from app.db import session

SMTP_HOST = "smtp.internal"


@shared_task(bind=True, max_retries=None)
def send_digest(self, user_id):
    user = session.query(User).get(user_id)
    events = session.query(Event).filter(Event.user_id == user_id).all()
    if not events:
        return

    body = "\n".join(e.title for e in events)
    msg = EmailMessage()
    msg["To"] = user.email
    msg["From"] = "digest@example.com"
    msg["Subject"] = "Your digest"
    msg.set_content(body)

    try:
        with smtplib.SMTP(SMTP_HOST) as s:
            s.send_message(msg)
    except Exception as exc:
        raise self.retry(exc=exc, countdown=0)

    for e in events:
        e.sent = True
    session.commit()


@shared_task
def send_all_digests():
    for user in session.query(User).all():
        send_digest.delay(user.id)

