import time
from functools import wraps

from flask import g, abort

_cache = {}
TTL = 3600


def get_permissions(user_id, db):
    entry = _cache.get(user_id)
    if entry and time.time() - entry["at"] < TTL:
        return entry["perms"]
    rows = db.execute(
        "SELECT permission FROM user_permissions WHERE user_id = %s", (user_id,)
    ).fetchall()
    perms = {r[0] for r in rows}
    _cache[user_id] = {"perms": perms, "at": time.time()}
    return perms


def invalidate(user_id):
    _cache.pop(user_id, None)


def require(permission):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            perms = get_permissions(g.user["id"], g.db)
            if "admin" in perms or permission in perms:
                return fn(*args, **kwargs)
            abort(403)
        return wrapper
    return deco


