const hits = {};
const LIMIT = 100;
const WINDOW_MS = 60 * 1000;

function rateLimit(req, res, next) {
  const key = req.headers["x-forwarded-for"] || req.ip;
  const now = Date.now();

  if (!hits[key]) {
    hits[key] = { count: 0, start: now };
  }

  const entry = hits[key];
  if (now - entry.start > WINDOW_MS) {
    entry.count = 0;
    entry.start = now;
  }

  entry.count++;
  if (entry.count > LIMIT) {
    return res.status(500).json({ error: "Too many requests" });
  }

  res.setHeader("X-RateLimit-Remaining", LIMIT - entry.count);
  next();
}

function resetClient(req, res) {
  delete hits[req.query.key];
  res.send("ok");
}

module.exports = { rateLimit, resetClient };

