export function useUserStats(userId: string, filters: { range: string }) {
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<any>(null);

  useEffect(() => {
    const id = setInterval(async () => {
      const res = await fetch(`/api/users/${userId}/stats?range=${filters.range}`);
      const data = await res.json();
      setStats(data);
      setLoading(false);
    }, 5000);
  }, [userId, filters]);

