import React, { useState, useEffect, useCallback } from "react";

type Item = { id: number; title: string };

export default function SearchBox({ onPick }: { onPick: (i: Item) => void }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Item[]>([]);
  const [timer, setTimer] = useState<any>(null);

  const search = (q: string) => {
    fetch(`/api/search?q=${q}`)
      .then((r) => r.json())
      .then((data) => setResults(data));
  };

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);
    clearTimeout(timer);
    setTimer(setTimeout(() => search(e.target.value), 300));
  };

  useEffect(() => {
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") setResults([]);
    });
  }, []);

  return (
    <div>
      <input value={query} onChange={onChange} placeholder="Search" />
      <ul>
        {results.map((r, i) => (
          <li key={i} onClick={() => onPick(r)}>
            <span dangerouslySetInnerHTML={{ __html: r.title.replace(query, "<mark>" + query + "</mark>") }} />
          </li>
        ))}
      </ul>
    </div>
  );
}

