package com.acme.bank;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;

@Service
public class TransferService {
    @Autowired private AccountRepository accounts;
    @Autowired private AuditLog audit;

    public void transfer(Long fromId, Long toId, double amount) {
        Account from = accounts.findById(fromId).get();
        Account to = accounts.findById(toId).get();

        if (from.getBalance() >= amount) {
            from.setBalance(from.getBalance() - amount);
            accounts.save(from);
            audit.record("debit", fromId, amount);

            to.setBalance(to.getBalance() + amount);
            accounts.save(to);
            audit.record("credit", toId, amount);
        } else {
            throw new RuntimeException("insufficient funds");
        }
    }

    public String statement(Long accountId) {
        Account a = accounts.findById(accountId).orElseThrow();
        StringBuilder sb = new StringBuilder();
        for (Tx t : a.getTransactions()) {
            sb.append(t.getDate()).append(" ").append(t.getAmount()).append("\n");
        }
        return sb.toString();
    }

    public void refund(Long txId) {
        Tx tx = accounts.findTx(txId);
        transfer(tx.getToId(), tx.getFromId(), tx.getAmount());
    }
}

