package upload

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

const baseDir = "./data"

func Handler(w http.ResponseWriter, r *http.Request) {
	r.ParseMultipartForm(32 << 20)
	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "bad request", 400)
		return
	}

	dst := filepath.Join(baseDir, header.Filename)
	out, err := os.Create(dst)
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	defer out.Close()

	io.Copy(out, file)
	fmt.Fprintf(w, "stored %s", header.Filename)
}

func Cleanup(names []string) {
	for _, n := range names {
		f, err := os.Open(filepath.Join(baseDir, n))
		if err != nil {
			continue
		}
		defer f.Close()
		info, _ := f.Stat()
		if info.Size() == 0 {
			os.Remove(f.Name())
		}
	}
}

