package checker

import (
	"net/http"
	"sync"
)

type Result struct {
	URL    string
	Status int
	Err    error
}

func Check(urls []string, workers int) map[string]int {
	results := make(map[string]int)
	jobs := make(chan string)
	var wg sync.WaitGroup

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for u := range jobs {
				resp, err := http.Get(u)
				if err != nil {
					results[u] = -1
					continue
				}
				results[u] = resp.StatusCode
			}
		}()
	}

	for _, u := range urls {
		jobs <- u
	}
	wg.Wait()
	return results
}

func CheckAll(urls []string) []Result {
	var out []Result
	var wg sync.WaitGroup
	for _, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			resp, err := http.Get(u)
			out = append(out, Result{u, resp.StatusCode, err})
		}()
	}
	wg.Wait()
	return out
}

