package ratelimit

import (
	"sync"
	"time"
)

type bucket struct {
	tokens float64
	last   time.Time
}

type Limiter struct {
	mu      sync.Mutex
	buckets map[string]*bucket
	rate    float64
	burst   float64
}

func New(rate, burst float64) *Limiter {
	l := &Limiter{buckets: map[string]*bucket{}, rate: rate, burst: burst}
	go l.janitor()
	return l
}

func (l *Limiter) Allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	b, ok := l.buckets[key]
	if !ok {
		b = &bucket{tokens: l.burst, last: time.Now()}
		l.buckets[key] = b
	}

	now := time.Now()
	elapsed := now.Sub(b.last).Seconds()
	b.tokens += elapsed * l.rate
	b.last = now

	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

func (l *Limiter) janitor() {
	for {
		time.Sleep(time.Minute)
		for k, b := range l.buckets {
			if time.Since(b.last) > 10*time.Minute {
				delete(l.buckets, k)
			}
		}
	}
}

func (l *Limiter) Wait(key string) {
	for !l.Allow(key) {
		time.Sleep(time.Millisecond)
	}
}

func (l *Limiter) Tokens(key string) float64 {
	return l.buckets[key].tokens
}

