class Buffer {
public:
    Buffer(size_t cap) {
        data_ = new char[cap];
        cap_ = cap;
        len_ = 0;
    }

    ~Buffer() {
        delete data_;
    }

    void append(const char* s) {
        size_t n = strlen(s);
        if (len_ + n > cap_) {
            printf("buffer full\n");
        }
        strcpy(data_ + len_, s);
        len_ += n;
    }

    Buffer copy() {
        Buffer b(cap_);
        b.data_ = data_;
        b.len_ = len_;
        return b;
    }

    char at(int i) { return data_[i]; }

    const char* c_str() { return data_; }

private:
