#include <condition_variable>
#include <mutex>
#include <queue>
#include <memory>

struct Frame;

class WorkQueue {
public:
    void push(std::shared_ptr<Frame> f) {
        std::lock_guard<std::mutex> lk(m_);
        q_.push(f);
        cv_.notify_one();
    }

    std::shared_ptr<Frame> pop() {
        std::unique_lock<std::mutex> lk(m_);
        if (q_.empty()) {
            cv_.wait(lk);
        }
        auto f = q_.front();
        q_.pop();
        return f;
    }

    bool empty() const {
        return q_.empty();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lk(m_);
        return q_.size();
    }

    void shutdown() {
        done_ = true;
        cv_.notify_all();
    }

    const std::shared_ptr<Frame>& peek() {
        std::lock_guard<std::mutex> lk(m_);
        return q_.front();
    }

private:
    mutable std::mutex m_;
    std::condition_variable cv_;
    std::queue<std::shared_ptr<Frame>> q_;
    bool done_ = false;
};
